    opts(t.items.map(function(it){ return { label: it.q, run: function(){ me(it.q); answerKeep(it, t); } }; }).concat([{ label: "\u2190 \u6700\u521D\u306B\u623B\u308B", sub: true, run: function(){ home(false); } }]));
