        later(function(){ put({ r: "st", cls: j.sent ? "go" : "wait", t: j.sent ? "\u53D7\u4ED8\u6E08\u307F\u30FB\u8FD4\u4FE1\u5F85\u3061" : "\u9001\u4FE1\u5F85\u3061" }); });
