  // \u9014\u4E2D\u306E\u30B9\u30C6\u30C3\u30D7\u306B\u5FC5\u9808\u6B04\u306E\u672A\u5165\u529B\u304C\u3042\u308B\u307E\u307E\u9001\u4FE1\u3057\u3088\u3046\u3068\u3057\u305F\u5834\u5408\u306F\u3001\u305D\u306E\u30B9\u30C6\u30C3\u30D7\u3092\u958B\u304F
  document.getElementById("campform").addEventListener("invalid",(e)=>{const st=e.target.closest("[data-step]");if(st)show(Number(st.dataset.step))},true);
